struct file_clone_range {
    __s64 src_fd;     // Source FD handle
    __u64 src_offset; // Offset in source file
    __u64 src_length; // Length of range (bytes)
    __u64 dest_offset;// Offset in destination file
};

struct file_clone_range fcr = {
    .src_fd = source_fd,
    .src_offset = 0,
    .src_length = length,
    .dest_offset = 0
};

// Clones data range (reflinks storage via CoW)
// dest_fd must be writable; files must be on same FS.
int ret = ioctl(dest_fd, FICLONERANGE, &fcr);

if (ret == -1) { /* handle error */ }
